package comments

import (
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"testing"

	"github.com/tdryer/difit-go/internal/editor"
	"github.com/tdryer/difit-go/internal/types"
)

// The expected file is generated by web/src/utils/golden.test.ts from the
// TypeScript implementation; both suites must agree with it.
type goldenFixtures struct {
	Output []struct {
		Name    string                    `json:"name"`
		Threads []types.DiffCommentThread `json:"threads"`
	} `json:"output"`
	Imports []struct {
		Name  string          `json:"name"`
		Input json.RawMessage `json:"input"`
		Raw   *string         `json:"raw"`
	} `json:"imports"`
	EditorArgs []struct {
		Template string `json:"template"`
	} `json:"editorArgs"`
}

type goldenExpected struct {
	Output []struct {
		Text string `json:"text"`
	} `json:"output"`
	Imports []struct {
		Serialized string `json:"serialized"`
		ImportID   string `json:"importId"`
		Error      string `json:"error"`
	} `json:"imports"`
	EditorArgs []struct {
		Args      []string `json:"args"`
		SpawnArgs []string `json:"spawnArgs"`
	} `json:"editorArgs"`
}

func readJSON(t *testing.T, name string, v any) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("..", "..", "testdata", "golden", name))
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, v); err != nil {
		t.Fatal(err)
	}
}

func TestGoldenFixtures(t *testing.T) {
	var fixtures goldenFixtures
	var expected goldenExpected
	readJSON(t, "comments.json", &fixtures)
	readJSON(t, "comments.expected.json", &expected)

	for i, c := range fixtures.Output {
		if got := FormatOutput(c.Threads); got != expected.Output[i].Text {
			t.Errorf("output %q:\ngot  %q\nwant %q", c.Name, got, expected.Output[i].Text)
		}
	}

	for i, c := range fixtures.Imports {
		raw := string(c.Input)
		if c.Raw != nil {
			raw = *c.Raw
		}
		want := expected.Imports[i]
		imports, err := ParseImportValue(raw)
		if want.Error != "" {
			if err == nil || err.Error() != want.Error {
				t.Errorf("import %q: got error %v, want %q", c.Name, err, want.Error)
			}
			continue
		}
		if err != nil {
			t.Errorf("import %q: unexpected error %v", c.Name, err)
			continue
		}
		if got := SerializeImports(imports); got != want.Serialized {
			t.Errorf("import %q:\ngot  %s\nwant %s", c.Name, got, want.Serialized)
		}
		if got := ImportID(imports); got != want.ImportID {
			t.Errorf("import %q: id %s, want %s", c.Name, got, want.ImportID)
		}
	}

	for i, c := range fixtures.EditorArgs {
		want := expected.EditorArgs[i]
		if got := editor.ParseArgsTemplate(c.Template); !slices.Equal(got, want.Args) {
			t.Errorf("template %q: got %q, want %q", c.Template, got, want.Args)
		}
		if got := editor.BuildArgs(c.Template, "/repo/dir with space/file.ts", 42); !slices.Equal(got, want.SpawnArgs) {
			t.Errorf("template %q: spawn args %q, want %q", c.Template, got, want.SpawnArgs)
		}
	}
}
